action.command:
python3 -c "
import csv
gt={}
with open('/workdir/data/ground_truth_female.csv') as f:
    for r in csv.DictReader(f): gt[r['PassengerId']]=int(r['label'])
pred={}
with open('/workdir/solution.csv') as f:
    for r in csv.DictReader(f): pred[r['PassengerId']]=int(r['prediction'])
tp=sum(1 for k in gt if gt[k]==1 and pred.get(k)==1)
fp=sum(1 for k in gt if gt[k]==0 and pred.get(k)==1)
fn=sum(1 for k in gt if gt[k]==1 and pred.get(k)==0)
prec=tp/(tp+fp); rec=tp/(tp+fn)
f1=2*prec*rec/(prec+rec)
print('F1 =', f1, 'TP,FP,FN=',tp,fp,fn)
"

